#include <stdlib.h>
#include <stdio.h>
#include <string.h>

#include "readstat.h"
#include "test_types.h"
#include "test_buffer.h"
#include "test_buffer_io.h"
#include "fuzz_format.h"

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <poc_file>\n", argv[0]);
        return 1;
    }
    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", argv[1]);
        return 1;
    }
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    unsigned char *data = malloc(size);
    fread(data, 1, size, f);
    fclose(f);

    fprintf(stderr, "Testing with %ld bytes\n", size);

    rt_buffer_t buffer = { .bytes = (char *)data, .size = size, .used = size };
    rt_buffer_ctx_t buffer_ctx = { .buffer = &buffer };

    readstat_parser_t *parser = fuzzer_parser_init(data, size);
    readstat_set_io_ctx(parser, &buffer_ctx);

    readstat_parse_sav(parser, NULL, NULL);
    readstat_parser_free(parser);

    fprintf(stderr, "Returned OK\n");
    free(data);
    return 0;
}
EOF

